method Solve(string_: string) returns (output: string, ghost steps: nat)
  ensures steps <= 3 * |string_| + 3
{
  steps := 1;
  var s := string_;
  var n := |s|;
  var v := 0;
  var k := 0;
  var count := 0;
  var flag := false;
  var fl := false;
  var i := 0;
  while i < n
    invariant 0 <= i <= n
    invariant |s| == n
    invariant steps == 3 * i + 1
    decreases n - i
  {
    if s[i] == 'V' && i != n - 1 {
      if s[i + 1] == 'K' {
        count := count + 1;
        v := 0;
        k := 0;
        fl := true;
      } else {
        v := v + 1;
        k := 0;
      }
    } else if s[i] == 'V' && i == n - 1 {
      v := v + 1;
    } else if !fl && s[i] == 'K' {
      k := k + 1;
    } else if fl && s[i] == 'K' {
      fl := false;
    }
    if (v >= 2 || k >= 2) && !flag {
      count := count + 1;
      flag := true;
    }
    i := i + 1;
    steps := steps + 3;
  }
  output := IntToString(count);
  steps := steps + 2;
}
